android.extraProguardRules:
# Archive readers used through reflection / ServiceLoader, and our own native module
-keep class expo.modules.comicarchive.** { *; }
-keep class com.github.junrar.** { *; }
-keep class org.apache.commons.compress.archivers.** { *; }
-keep class org.apache.commons.compress.compressors.** { *; }
# Optional dependencies of commons-compress / junrar that are not shipped
-dontwarn org.slf4j.**
-dontwarn org.apache.commons.compress.**
-dontwarn com.github.luben.zstd.**
-dontwarn org.brotli.dec.**
-dontwarn org.objectweb.asm.**
-dontwarn org.tukaani.xz.**
-dontwarn javax.annotation.**
